import{_ as l,o as t,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Crimson/Seastar OSD Meeting 2018-11-07","description":"","frontmatter":{"title":"Crimson/Seastar OSD Meeting 2018-11-07","date":"2018-11-07T00:00:00.000Z","updated":"2018-11-08T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","内存复制","共享缓存"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-11-07.md","filePath":"posts/2018/Crimson_Seastar_OSD_Meeting_2018-11-07.md","lastUpdated":1780459816000}'),s={name:"posts/2018/Crimson_Seastar_OSD_Meeting_2018-11-07.md"};function n(o,i,a,g,_,p){return t(),e("div",null,[...i[0]||(i[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2018年11月7日</p><p><strong>参会人员</strong>： triple penguin, Mark, Sage, Ricardo, Linda, Greg, Jim 等</p><p><strong>会议主题</strong>： Ceph分布式存储系统性能优化与改进</p><p><strong>会议内容</strong>：</p><ul><li><strong>共享OSD映射或共享缓存</strong>： <ul><li>讨论了避免在核心之间进行通信以避免死锁的可能性，并考虑了将连接和消息代理分散到不同核心的方法。</li><li>认为将连接和消息代理分散到不同核心可以提高性能，并简化实现。</li><li>讨论了将连接和消息代理分散到不同核心的挑战，例如客户端需要了解OSD的CPU数量和端口信息。</li></ul></li><li><strong>内存复制</strong>： <ul><li>讨论了内存复制的性能影响，并考虑了使用共享缓存来避免内存复制。</li><li>认为在创建新的OSD映射时进行内存复制是罕见的，因此可以接受其性能影响。</li><li>讨论了将消息代理分散到不同核心的方法，例如使用服务器-客户端架构。</li></ul></li><li><strong>系统消息中的断开连接</strong>： <ul><li>讨论了实现系统消息中的断开连接的可能性。</li><li>认为这需要接口更改，例如连接和消息代理。</li><li>讨论了如何处理连接和消息代理的碎片化，以及如何确保消息的完整性和可靠性。</li></ul></li><li><strong>PG分片</strong>： <ul><li>讨论了PG分片的性能影响，并考虑了使用PG分片来提高性能。</li><li>认为PG分片可以减少客户端到PG的通信，并提高性能。</li><li>讨论了PG分片的挑战，例如客户端需要了解PG分片信息。</li></ul></li><li><strong>权限路径和共享缓存</strong>： <ul><li>讨论了权限路径和共享缓存的性能影响。</li><li>认为权限路径和共享缓存可以提高性能，并减少内存使用。</li><li>讨论了权限路径和共享缓存的实现方法。</li></ul></li><li><strong>短路和读写路径</strong>： <ul><li>讨论了短路和读写路径的性能影响。</li><li>认为短路可以提高性能，并减少开销。</li><li>讨论了短路和读写路径的实现方法。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>实现系统消息中的断开连接。</li><li>评估PG分片的性能影响。</li><li>实现权限路径和共享缓存。</li><li>实现短路和读写路径。</li></ul></li></ul><p><strong>会议结论</strong>：</p><ul><li>会议讨论了Ceph分布式存储系统性能优化和改进的多个方面。</li><li>讨论了各种方法和技术的优缺点。</li><li>确定了后续行动计划。</li></ul><p><strong>关键词</strong>： Ceph, 分布式存储, 性能优化, 内存复制, 共享缓存, PG分片, 权限路径, 短路, 读写路径</p>',9)])])}const S=l(s,[["render",n]]);export{d as __pageData,S as default};
